(function(){
 const scenarios=[],assert=(x,m)=>{if(!x)throw Error(m);},run=(name,fn)=>{fn();scenarios.push(name);};let model,api,before;
 run('native command translates all fourteen tools with one undo',()=>{nativeInit(0,{series:[]});model=nativeModel;api=nativeAPI;for(const type of Aster.DRAWING_TYPES){const n=type==='freehand'?5:Aster.drawingPointCount(type);nativeCommand('addDrawing',[{id:type,type,points:Array.from({length:n},(_,i)=>({time:10.25+i,price:20+i})),...(type==='text'?{text:'raw label'}:{})}]);}before=api.saveDrawings();const n=model.drawings.undoStack.length;const receipt=nativeCommand('translateDrawings',[Aster.DRAWING_TYPES,{deltaTimeMs:.5,deltaPrice:3}]);assert(receipt.changed===14&&!receipt.invalidationFailed,'receipt');assert(model.drawings.undoStack.length===n+1,'one undo');for(const d of model.drawings.items)for(let i=0;i<d.points.length;i++)assert(d.points[i].time===10.75+i&&d.points[i].price===23+i,'anchor');api.undo();assert(api.saveDrawings()===before,'undo exact');api.redo();});
 run('overflow and mixed binding reject whole group without history writes',()=>{const items=model.drawings.items,u=model.drawings.undoStack,r=model.drawings.redoStack;let threw=false;try{api.translateDrawings(['trendline','text'],{deltaTimeMs:8640000000000000,deltaPrice:0});}catch{threw=true;}assert(threw&&items===model.drawings.items&&u===model.drawings.undoStack&&r===model.drawings.redoStack,'atomic overflow');api.addAxis({id:'other',panel:'price'});api.addDrawing({id:'bound',type:'horizontal',axisId:'other',points:[{time:1,price:2}]});const current=model.drawings.items,history=model.drawings.undoStack;threw=false;try{api.translateDrawings(['trendline','bound'],{deltaTimeMs:1,deltaPrice:1});}catch{threw=true;}assert(threw&&current===model.drawings.items&&history===model.drawings.undoStack,'mixed binding');});
 run('noop and observer failure preserve committed success and cleanup',()=>{const u=model.drawings.undoStack,r=model.drawings.redoStack;const noop=api.translateDrawings(['trendline'],{deltaTimeMs:-0,deltaPrice:0});assert(noop.changed===0&&u===model.drawings.undoStack&&r===model.drawings.redoStack,'noop');api.invalidate=()=>{throw Error('observer');};const result=api.translateDrawings(['trendline'],{deltaTimeMs:1,deltaPrice:1});assert(result.changed===1&&result.invalidationFailed,'observer receipt');const store=model.store;model.dispose();assert(store.listeners.size===0,'listeners');});
 return JSON.stringify({case:'drawing-translation-quickjs',passed:true,checks:3,scenarios});
})()
